// import React from "react";

function About() {
  return (
    <div className= "about" >
      <h1>The Memories</h1>
      <p>
        The ritual of drinking chai every evening with your family, with your friends while growing up is something that I have inherently carried with me to this day. An object of comfort offered during sickness, loneliness, moments of deep thought, a go-to drink anywhere, the cause of resentment towards coffee.
      </p>
      <p>
        Carrying a glimpse of culture through different travels, to different moves and stages of life. The only source of comfort away from home, a bonding moment familiar and unforgotten. 
      </p>
      <p>
        Chai can be a lot of things for a lot of people, open for interpretation, for me it's a symbol of grounding, of connecting myself back to my roots in moments I feel lost or lonely.
      </p>
      <p>
        Also a way of forcing the chai-propaganda on any acquaintance I meet, or could be any beverage, any similar object someone co-relates to the feeling of home.
      </p>
    </div>
  );
}

export default About;
